import{c as d,Q as r,j as e,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Auto-load 下沉評估 — 5 源逐段 TYPE 分類 + on-demand 下沉執行","description":"","frontmatter":{"title":"Auto-load 下沉評估 — 5 源逐段 TYPE 分類 + on-demand 下沉執行","date":"2026-06-05T00:00:00.000Z","branch":"feature/autoload-research-merge-2026-06-05","method":"逐段 byte 量測（wc -c / awk）+ TYPE 分類（判準 core.md §Framework Integrity）+ 主對話親自驗指針 anchor","result":"回收 405 byte（18,999 → 18,594），餘裕 1 → 406","trigger":"使用者要求「12 原則下哪些 auto-load 內容可下沉到 on-demand ref」","type":"assessment + execution report"},"headers":[],"relativePath":"research/reports/archive/2026-06-05-autoload-offload-assessment.md","filePath":"research/reports/archive/2026-06-05-autoload-offload-assessment.md","lastUpdated":1780842316000}'),o={name:"research/reports/archive/2026-06-05-autoload-offload-assessment.md"};function n(s,t,l,h,i,c){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="auto-load-下沉評估與執行" tabindex="-1">Auto-load 下沉評估與執行 <a class="header-anchor" href="#auto-load-下沉評估與執行" aria-label="Permalink to &quot;Auto-load 下沉評估與執行&quot;">​</a></h1><blockquote><p><strong>背景</strong>：承接同 session #5/#6 gap 加入後，auto-load 逼近 19,000 byte cap（剩 1 byte）。使用者要求在 12-Rule Canon 框架下，評估哪些常駐內容可下沉到 path-scoped on-demand ref，完整量測後執行並更新文件。</p></blockquote><hr><h2 id="_0-tl-dr" tabindex="-1">0. TL;DR <a class="header-anchor" href="#_0-tl-dr" aria-label="Permalink to &quot;0. TL;DR&quot;">​</a></h2><ul><li><strong>判準</strong>：core.md §Framework Integrity「移除後 Claude 在哪犯錯？」——移除<strong>不即時致錯</strong>者（純參考表 / 低頻細節 / 已在 ref 重複 / rationale）可下沉；12-Rule 強制條文 + 安全紅線 + 語言鐵律 + 核心輸出紀律 = TYPE A 不可下沉。</li><li><strong>執行（保守方案，零行為風險）</strong>：下沉 2 段 → 回收 <strong>405 byte</strong>，18,999 → <strong>18,594</strong>（餘裕 1 → 406），重回「12-Rule Canon 完整正當化區間」舒適帶。</li><li><strong>守紀律關鍵</strong>：Dynamic Workflow 段<strong>不整段下沉</strong>——其中「subagent/workflow verdict 非證據，必 grep 重驗」是 R12.1 延伸鐵律（TYPE A），保留於 auto-load；僅下沉六大 pattern / token guardrail 細節。</li><li><strong>無新增 byte 預算</strong>：下沉的 ref 落點全部<strong>事前親 grep 確認內容實存</strong>（無死鏈），control-semantics 表更是 error-handling.md 已 100% 重複。</li></ul><hr><h2 id="_1-量測基準-逐段-byte-分布" tabindex="-1">1. 量測基準（逐段 byte 分布） <a class="header-anchor" href="#_1-量測基準-逐段-byte-分布" aria-label="Permalink to &quot;1. 量測基準（逐段 byte 分布）&quot;">​</a></h2><p>五源現況（執行前）：18,999 / 19,000 byte。</p><table tabindex="0"><thead><tr><th>檔</th><th>byte</th><th>行數</th></tr></thead><tbody><tr><td>CLAUDE.md</td><td>2,585</td><td>43</td></tr><tr><td>core.md</td><td>9,062</td><td>101</td></tr><tr><td>context-management.md</td><td>2,007</td><td>27</td></tr><tr><td>output-discipline.md</td><td>1,490</td><td>21</td></tr><tr><td>subagent-strategy.md</td><td>3,855</td><td>67</td></tr></tbody></table><h3 id="core-md-段分布-最大檔-逐-段" tabindex="-1">core.md 段分布（最大檔，逐 <code>##</code> 段） <a class="header-anchor" href="#core-md-段分布-最大檔-逐-段" aria-label="Permalink to &quot;core.md 段分布（最大檔，逐 `##` 段）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>段</th><th>byte</th><th>TYPE</th></tr></thead><tbody><tr><td>語言</td><td>235</td><td>A（繁中鐵律）</td></tr><tr><td>生產環境安全紅線</td><td>148</td><td>A</td></tr><tr><td>§R1–§R12（12 段合計）</td><td>~5,539</td><td><strong>A（行為契約，全不可下沉）</strong></td></tr><tr><td>Framework Integrity</td><td>811</td><td>A（含 byte cap 機制）</td></tr><tr><td>暫存檔案</td><td>193</td><td>A（路徑慣例，高頻）</td></tr><tr><td>長任務執行</td><td>297</td><td>A（Bash 慣例，高頻致錯）</td></tr><tr><td>長期記憶回路</td><td>617</td><td>A（self-improving 觸發，高頻）</td></tr><tr><td>Git 工作流程</td><td>1,033</td><td>A 紅線 + C 細節（worktree/PR 衝突 rationale 可下沉，本輪未動）</td></tr></tbody></table><h3 id="subagent-strategy-md-段分布" tabindex="-1">subagent-strategy.md 段分布 <a class="header-anchor" href="#subagent-strategy-md-段分布" aria-label="Permalink to &quot;subagent-strategy.md 段分布&quot;">​</a></h3><table tabindex="0"><thead><tr><th>段</th><th>byte（執行前）</th><th>TYPE</th><th>裁決</th></tr></thead><tbody><tr><td>Agent Input Security</td><td>307</td><td>A</td><td>保留（injection 防護高頻）</td></tr><tr><td>委派決策</td><td>705</td><td>A</td><td>保留（核心判準）</td></tr><tr><td>拓撲規則 Fan-out</td><td>591</td><td>A</td><td>保留（並行紀律）</td></tr><tr><td><strong>Agent 控制語義表</strong></td><td><strong>638</strong></td><td><strong>C</strong></td><td><strong>✅ 下沉</strong>（error-handling.md 已全含）</td></tr><tr><td>Routines</td><td>112</td><td>A</td><td>保留</td></tr><tr><td>Frozen Snapshot</td><td>120</td><td>A</td><td>保留</td></tr><tr><td>Advisor 模式</td><td>172</td><td>A</td><td>保留</td></tr><tr><td>模型選擇</td><td>493</td><td>A</td><td>保留</td></tr><tr><td>Background Agent</td><td>267</td><td>A</td><td>保留</td></tr><tr><td><strong>Dynamic Workflow 紀律</strong></td><td><strong>412</strong></td><td><strong>A+C 混合</strong></td><td><strong>✅ 部分下沉</strong>（保留 verdict 鐵律，下沉 pattern 細節）</td></tr></tbody></table><hr><h2 id="_2-type-分類原則-12-rule-框架" tabindex="-1">2. TYPE 分類原則（12-Rule 框架） <a class="header-anchor" href="#_2-type-分類原則-12-rule-框架" aria-label="Permalink to &quot;2. TYPE 分類原則（12-Rule 框架）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>TYPE</th><th>定義</th><th>下沉？</th><th>範例</th></tr></thead><tbody><tr><td><strong>A</strong></td><td>移除即時致錯</td><td>❌ 不可</td><td>§R1–§R12、安全紅線、繁中鐵律、核心輸出紀律、委派決策</td></tr><tr><td><strong>C</strong></td><td>rationale / 低頻參考 / 純對照表 / 已在 ref 重複</td><td>✅ 下沉 refs</td><td>控制語義表、workflow pattern 細節、cache 監控公式</td></tr><tr><td><strong>D</strong></td><td>與他段 / ref 重複</td><td>✅ 刪</td><td>model-drift（已在 prompt-lifecycle）</td></tr></tbody></table><blockquote><p><strong>混合段處理</strong>：一段內可同時含 A 鐵律 + C 細節（如 Dynamic Workflow）→ <strong>拆</strong>：鐵律句留 auto-load，細節下沉，留指針。不整段下沉。</p></blockquote><hr><h2 id="_3-執行紀錄-保守方案" tabindex="-1">3. 執行紀錄（保守方案） <a class="header-anchor" href="#_3-執行紀錄-保守方案" aria-label="Permalink to &quot;3. 執行紀錄（保守方案）&quot;">​</a></h2><h3 id="下沉-1-agent-控制語義表-零損" tabindex="-1">下沉 1：Agent 控制語義表（零損） <a class="header-anchor" href="#下沉-1-agent-控制語義表-零損" aria-label="Permalink to &quot;下沉 1：Agent 控制語義表（零損）&quot;">​</a></h3><ul><li><strong>前</strong>：638 byte 完整三語義對照表（interrupt/steer/gate）+ pause_turn 說明</li><li><strong>後</strong>：1 行指針 → <code>refs/error-handling.md §Agent 控制語義</code></li><li><strong>零損依據</strong>：error-handling.md L48-58 已 100% 含相同表（親 grep 確認）</li><li><strong>回收</strong>：~425 byte</li></ul><h3 id="下沉-2-dynamic-workflow-紀律-拆-a-c" tabindex="-1">下沉 2：Dynamic Workflow 紀律（拆 A/C） <a class="header-anchor" href="#下沉-2-dynamic-workflow-紀律-拆-a-c" aria-label="Permalink to &quot;下沉 2：Dynamic Workflow 紀律（拆 A/C）&quot;">​</a></h3><ul><li><strong>保留（TYPE A 鐵律）</strong>：「subagent/workflow verdict 非證據，採信前必機械 grep 重驗（連 agent 轉述的確定性結果亦不可信，見 §R12.1）」</li><li><strong>下沉（TYPE C）</strong>：六大 pattern / 「when not to use」token guardrail / 全紀錄 → <code>harness-meta-GOTCHAS.md §Dynamic Workflow</code> + research 檔</li><li><strong>回收淨額</strong>：併下沉 1 後總回收 405 byte</li></ul><h3 id="死鏈防範-過程修正" tabindex="-1">死鏈防範（過程修正） <a class="header-anchor" href="#死鏈防範-過程修正" aria-label="Permalink to &quot;死鏈防範（過程修正）&quot;">​</a></h3><ul><li>執行中一度把 Dynamic Workflow 指針誤改指向 <code>refs/harness-design.md</code>（grep = 0 hits，內容不存在）→ 立即修回確實存在的 <code>harness-meta-GOTCHAS.md</code>（2 hits）。</li><li><strong>教訓</strong>：下沉留指針前，必親 grep 確認 ref 落點 anchor 實存，否則造成死鏈（R12 Fail Loud 攔截）。</li></ul><hr><h2 id="_4-驗證-確定性-gate-主對話親自跑" tabindex="-1">4. 驗證（確定性 gate，主對話親自跑） <a class="header-anchor" href="#_4-驗證-確定性-gate-主對話親自跑" aria-label="Permalink to &quot;4. 驗證（確定性 gate，主對話親自跑）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>檢查</th><th>結果</th></tr></thead><tbody><tr><td>五源 byte</td><td><strong>18,594 / 19,000</strong>（餘裕 406）</td></tr><tr><td>指針 <code>error-handling.md §Agent 控制語義</code></td><td>✅ 1 anchor 實存</td></tr><tr><td>指針 <code>harness-meta-GOTCHAS.md §Dynamic Workflow</code></td><td>✅ 2 hits 實存</td></tr><tr><td>指針 research dynamic-workflows 檔</td><td>✅ 實存</td></tr><tr><td>healthcheck</td><td><strong>PASS 110 / WARN 3 / FAIL 0</strong>（含 Auto-load Budget Gate PASS）</td></tr></tbody></table><hr><h2 id="_5-未執行的下沉候選-供未來-cycle" tabindex="-1">5. 未執行的下沉候選（供未來 cycle） <a class="header-anchor" href="#_5-未執行的下沉候選-供未來-cycle" aria-label="Permalink to &quot;5. 未執行的下沉候選（供未來 cycle）&quot;">​</a></h2><p>保守方案僅取零損 2 段。以下候選經評估可行但本輪未動（守 ≤1 cycle 紀律 + 需更細拆分）：</p><table tabindex="0"><thead><tr><th>候選</th><th>byte</th><th>落點</th><th>為何延後</th></tr></thead><tbody><tr><td>Git 工作流程 worktree/PR 衝突細節</td><td>~500</td><td>新 ref 或 harness-loop</td><td>需拆「紅線句保留」vs「rationale 下沉」，多一層判斷</td></tr><tr><td>context-management 監控 cache 公式</td><td>~450</td><td>cache-health-metrics.md（已存在）</td><td>需確認公式不在高頻路徑</td></tr></tbody></table><p>→ 兩者合計可再回收 ~950 byte，降到 ~17,650。建議走 <code>/autoload-evolution</code> 獨立 cycle 執行。</p><hr><h2 id="_5b-反向稽核發現-refs-→-auto-load-2026-06-05-追加" tabindex="-1">5b. 反向稽核發現（refs → auto-load，2026-06-05 追加） <a class="header-anchor" href="#_5b-反向稽核發現-refs-→-auto-load-2026-06-05-追加" aria-label="Permalink to &quot;5b. 反向稽核發現（refs → auto-load，2026-06-05 追加）&quot;">​</a></h2><blockquote><p><strong>方法（反向思考）</strong>：不從 auto-load 往外查死鏈，而是從 refs/ 回看 auto-load 鏈健康度。建「ref ↔ auto-load 引用矩陣」（grep -F 反查，注意 <code>.md</code> 的 <code>.</code> 會被正則吃掉 → 必用 <code>-F</code> 固定字串 + 陣列展開檔列表，否則全 0 假陰性）。委派 researcher 機械掃描，主對話親自 grep 重驗每條 verdict。</p></blockquote><h3 id="矩陣結論" tabindex="-1">矩陣結論 <a class="header-anchor" href="#矩陣結論" aria-label="Permalink to &quot;矩陣結論&quot;">​</a></h3><ul><li><strong>死鏈 0</strong>：auto-load 所有 <code>refs/xxx.md §anchor</code> 指針的目標檔 + anchor 全實存。</li><li><strong>真孤兒 0</strong>：9 個「auto-load 0 直接引用」的 ref 全部經 refs/README + trigger-index 二跳可達（非完全不可達）。</li><li><strong>trigger-index 自身 0 個 auto-load 直接引用</strong>（MEMORY 早記的已知斷鏈，現況仍然；二跳工具用，非阻塞）。</li></ul><h3 id="修正的真實缺陷-親驗屬實" tabindex="-1">修正的真實缺陷（親驗屬實） <a class="header-anchor" href="#修正的真實缺陷-親驗屬實" aria-label="Permalink to &quot;修正的真實缺陷（親驗屬實）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>缺陷</th><th>親驗</th><th>修正</th></tr></thead><tbody><tr><td>1</td><td><strong>byte cap stale</strong>：<code>harness-loop.md:21</code>（canonical TEST gate）寫 <code>≤18,000</code>，auto-load 本體已 19,000</td><td>✅ grep 確認</td><td>改為 19,000（canonical 須現值）</td></tr><tr><td>2</td><td><code>model-upgrade-harness-tuning.md:78-79</code> 歷史提案快照寫 18,000</td><td>✅ grep 確認</td><td><strong>加註不竄改</strong>（歷史快照保留 + 標明現值 19,000）</td></tr><tr><td>3</td><td><code>removed-content-manifest.txt</code> 未登錄 refs/README</td><td>✅ grep=0</td><td>refs/README 加機制資料登錄行</td></tr><tr><td>4</td><td>refs/README L3 寫「12 docs」但實列 17</td><td>✅</td><td>改 17</td></tr><tr><td>5</td><td>refs/README L42 宣稱 agent-team-patterns 被 subagent-strategy 引用，實際 grep=0</td><td>✅</td><td>改誠實標注（SA-2 待辦未建入口）</td></tr></tbody></table><h3 id="關鍵判斷-researcher-未分辨、主對話拍板" tabindex="-1">關鍵判斷（researcher 未分辨、主對話拍板） <a class="header-anchor" href="#關鍵判斷-researcher-未分辨、主對話拍板" aria-label="Permalink to &quot;關鍵判斷（researcher 未分辨、主對話拍板）&quot;">​</a></h3><p><strong>同樣的「18,000」，一個該改一個不該改</strong>：</p><ul><li><code>harness-loop.md</code> = harness loop <strong>canonical 定義</strong>（CLAUDE.md 直接引用）→ 必須現值 → <strong>改 19,000</strong></li><li><code>model-upgrade-harness-tuning.md</code> = <strong>歷史提案快照</strong>（記錄 2026-05 當時 cap）→ 竄改會破壞紀錄真實性 → <strong>加註不改數字</strong></li></ul><p>→ 反向稽核的最高價值：抓到「ref 內 stale 閾值會誤導 harness 預檢」這類<strong>正向稽核（從 auto-load 出發）看不到</strong>的缺陷——因為這些 ref 不被 auto-load 直接引用，只在跑 harness loop / model-upgrade 時才載入，正向掃不到。</p><hr><h2 id="_6-結論" tabindex="-1">6. 結論 <a class="header-anchor" href="#_6-結論" aria-label="Permalink to &quot;6. 結論&quot;">​</a></h2><ul><li><strong>下沉是 auto-load 飽和的正解</strong>（優於上調 cap）：cap 上調受 core.md L79 自身禁令約束（不接受為單一規則湊 byte）；下沉把低頻內容移到「需要時才載入」的 path-scoped ref，<strong>既守 byte 預算又零功能損失</strong>。</li><li><strong>12-Rule 框架下的下沉鐵律</strong>：強制條文（§R1–§R12）+ 安全紅線 + 鐵律句永不下沉；純參考 / 低頻 / 重複內容才下沉；混合段拆而非整段移。</li><li><strong>餘裕 406 byte</strong>：足夠容下次小幅規則增補，但近滿狀態應持續以下沉換空間，非反覆逼近 cap。</li></ul><hr><p><em>評估日期：2026-06-05 | 方法：逐段 byte 量測 + TYPE 分類 + 主對話親自驗指針 | 回收 405 byte | healthcheck PASS 110/0 | 保守零損方案</em></p>',49)])])}const b=d(o,[["render",n]]);export{u as __pageData,b as default};
